"""One-off: lessons from the practice sessions we already played (logs/runs + logs/sessions):
per case the worst and the best run, so the lead sees what made the difference."""
import glob, json, os, sys
from types import SimpleNamespace as NS
from arena_kit.cli import load_env
load_env()
from buyer import llm, memory

complete = llm.complete_from_env()
cases = {c["case_id"]: c for c in json.load(open("logs/cases/practice.json"))}
runs = {}
for f in sorted(glob.glob("logs/runs/P*.json")):
    d = json.load(open(f))
    if d["result"].get("score") is not None:
        runs.setdefault(d["case"], []).append((d["result"]["score"], f, d))
n = 0
for case_id, rs in sorted(runs.items()):
    rs.sort(key=lambda r: r[0])
    for score, f, d in ([rs[0], rs[-1]] if rs[-1][0] - rs[0][0] > 0.02 else [rs[-1]]):
        sides = {}
        for x in d["notes"]:
            sid = x.get("supplier")
            if x["what"] == "setup":
                sides[sid] = NS(sid=sid, prof=x.get("profile") or {}, quote=x.get("quote_at_terms"), ours=[], theirs=[], fraction=0.3, mood=None)
            elif x["what"] == "send" and sid in sides and x.get("state") == "open":
                sides[sid].ours.append(x["ours"]); sides[sid].theirs.append(x["theirs"])
        result = dict(d["result"])
        sess = f"logs/sessions/practice/{os.path.basename(f)}"
        if os.path.exists(sess):
            result["trace"] = json.load(open(sess))["result"].get("trace")
        won = sides.get(result.get("supplier_id"))
        if won and result.get("terms", {}).get("unit_price"):
            won.theirs.append(result["terms"]["unit_price"])
        row = memory.record(cases[case_id], NS(sides=sides), result, complete)
        n += 1
        print(case_id, round(score, 3), row and row["lesson"])
print(n, "lessons")
